import {gunzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
const bytes=gunzipSync(Buffer.from('','base64'));
if(createHash('sha256').update(bytes).digest('hex')!=='bbc142b8dc55bf110aa605bcf644f04b5697fca3e91f67ce53ed04665385b071')throw Error('RELEASE_HASH_MISMATCH');
for(const [name,code]of Object.entries(JSON.parse(bytes)))await Bun.write(new URL('./'+name,import.meta.url),code);
const app=await import(new URL('./balloon-entry.mjs',import.meta.url).href);
export default app.default;

